# 에이전트용 운영 도구: 읽기/쓰기 권한을 나누고 모든 호출을 기록 (가상)
import json
AUDIT = []


def tool(scope):
    def wrap(fn):
        def run(agent, **args):
            ok = scope in agent["scopes"]
            AUDIT.append({"agent": agent["name"], "tool": fn.__name__,
                          "args": args, "result": "ok" if ok else "denied"})
            if not ok:
                return f"거부: {fn.__name__} 은 '{scope}' 권한이 필요"
            return fn(**args)
        return run
    return wrap


@tool("read")
def get_user(user_id):
    return {"id": user_id, "manner": 36.5, "phone": "010-****-1234"}  # 연락처는 가려서 준다


@tool("write")
def assign_inquiry(inquiry_id, to):
    return f"문의 {inquiry_id} → {to} 배정"


cs_bot = {"name": "cs-agent", "scopes": {"read"}}
print(get_user(cs_bot, user_id="u42"))
print(assign_inquiry(cs_bot, inquiry_id="q7", to="분쟁팀"))
for row in AUDIT:
    print(json.dumps(row, ensure_ascii=False))

# 채팅 속 전화번호 우회 표기 잡기: 띄어쓰기·한글 숫자·영문 o 섞기 (가상)
import re
KO = {"공": "0", "영": "0", "일": "1", "이": "2", "삼": "3", "사": "4",
      "오": "5", "육": "6", "칠": "7", "팔": "8", "구": "9", "o": "0"}


def digits(text):
    s = "".join(KO.get(ch, ch) for ch in text)
    return re.sub(r"\D", "", s)


BLOCKED = {"01012345678"}   # 사기 이력 번호(가상)
for msg in ["010 1234 5678 로 연락주세요", "공일공-일이삼사-오육칠팔", "o1o.1234.5678", "가격 12,000원"]:
    d = digits(msg)
    hit = any(b in d for b in BLOCKED)
    print(f"{msg} → {d} {'차단' if hit else '통과'}")

# 서비스 이름으로 Client·Presenter 를 찾아 쓰기 — 분기문 없이 (발표의 메타프로그래밍을 파이썬으로)
class FleamarketClient:
    def user_info(self, uid):
        return {"status": 2, "articles": 14}


class FleamarketPresenter:
    keys = ["status", "articles"]

    def status(self, raw):
        return {1: "정상", 2: "이용 제한"}[raw["status"]]


def user_info(service, uid):
    name = service.capitalize()
    client = globals().get(f"{name}Client")
    presenter = globals().get(f"{name}Presenter")
    if not client or not presenter:            # 구현 안 된 서비스 → 오류 대신 안내
        return {"error": f"{service} 는 아직 지원하지 않음"}
    raw, p = client().user_info(uid), presenter()
    return {k: getattr(p, k)(raw) if hasattr(p, k) else raw[k] for k in p.keys}


print(user_info("fleamarket", "u1"))
print(user_info("realty", "u1"))
